package net.officefloor.hq.app.audit;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * The sheet's audit lines as the file holds them, newest first; only a person's when a name is given. With a name,
 * the matching lines of the sheet's descendants follow (each sheet's newest first, sheets by id); when that
 * person was transferred in, the lines about them from the sheet they came from follow, newest first.
 */
public class LoadAuditLines {
    public void service(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "name", required = false) String name, Audit audit, People people, Sheets sheets,
            ObjectResponse<List<String>> response) {
        List<String> lines = new ArrayList<>(audit.lines(sheetId, name));
        if (name != null && !name.isBlank()) {
            for (String descendant : sheets.descendants(sheetId).stream().sorted().toList()) {
                lines.addAll(audit.lines(descendant, name));
            }
            String origin = people.originOf(sheetId, name);
            if (origin != null) {
                lines.addAll(audit.lines(origin, name));
            }
        }
        response.send(lines);
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.setting.Settings;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The lines that only report figures: they never carry for=. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;

    private final ObjectProvider<Settings> settings;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<Settings> settings) {
        this.file = Path.of(path);
        this.settings = settings;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public void record(String entry) {
        append(delegated(entry));
    }

    /**
     * The entry, ending with for=<the steward who delegated> when its by= user acts as a steward by a
     * delegation covering the sheet's today — unless it is a line that only reports figures.
     */
    private String delegated(String entry) {
        String[] fields = entry.split(" ");
        if (FIGURES.contains(fields[0])) {
            return entry;
        }
        String sheet = null;
        String by = null;
        for (String field : fields) {
            if (sheet == null && field.startsWith("sheet=")) {
                sheet = field.substring("sheet=".length());
            } else if (by == null && field.startsWith("by=")) {
                by = field.substring("by=".length());
            }
        }
        if (sheet == null || by == null) {
            return entry;
        }
        String delegator = settings.getObject().delegator(sheet, by);
        return delegator == null ? entry : entry + " for=" + delegator;
    }

    private synchronized void append(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is rolled back
     * (refused by a later step) writes no line. Outside a transaction it is appended at once.
     */
    public void recordOnCommit(String raw) {
        String entry = delegated(raw);
        if (TransactionSynchronizationManager.isSynchronizationActive()) {
            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
                @Override
                public void afterCommit() {
                    append(entry);
                }
            });
        } else {
            append(entry);
        }
    }

    /**
     * The sheet's lines exactly as the file holds them, newest first. With a name (not blank), only
     * the lines carrying name=<it> or person=<it>, compared as names are (case and surrounding
     * spaces ignored). Read from the file: the viewer is not a second record.
     */
    public synchronized List<String> lines(String sheet, String name) {
        String wanted = name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
        List<String> found = new ArrayList<>();
        if (!Files.exists(file)) {
            return found;
        }
        List<String> all;
        try {
            all = Files.readAllLines(file, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        for (String line : all) {
            List<String[]> fields = fields(line);
            if (!has(fields, "sheet", sheet, false)) {
                continue;
            }
            if (!wanted.isEmpty() && !has(fields, "name", wanted, true) && !has(fields, "person", wanted, true)) {
                continue;
            }
            found.add(line);
        }
        Collections.reverse(found);
        return found;
    }

    /**
     * A claim's timeline: the sheet's lines about it exactly as the file holds them, newest first. With a number,
     * the lines carrying number=<it>; without one, the lines carrying no number that name its person (compared as
     * names are), amount and date together. Read from the file: the timeline is not a second record.
     */
    public synchronized List<String> claimLines(String sheet, String number, String person, String amount,
            String date) {
        String wanted = person.trim().toLowerCase(Locale.ROOT);
        List<String> found = new ArrayList<>();
        if (!Files.exists(file)) {
            return found;
        }
        List<String> all;
        try {
            all = Files.readAllLines(file, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        for (String line : all) {
            List<String[]> fields = fields(line);
            if (!has(fields, "sheet", sheet, false)) {
                continue;
            }
            boolean about = number != null && !number.isEmpty()
                    ? has(fields, "number", number, false)
                    : !hasKey(fields, "number") && has(fields, "person", wanted, true)
                            && has(fields, "amount", amount, false) && has(fields, "date", date, false);
            if (about) {
                found.add(line);
            }
        }
        Collections.reverse(found);
        return found;
    }

    /** Whether the line carries a field with the key. */
    private static boolean hasKey(List<String[]> fields, String key) {
        return fields.stream().anyMatch(field -> field[0].equals(key));
    }

    /** Whether a field key=value is among the line's fields (a name compared trimmed, case ignored). */
    private static boolean has(List<String[]> fields, String key, String value, boolean asName) {
        for (String[] field : fields) {
            if (field[0].equals(key)) {
                String v = asName ? field[1].trim().toLowerCase(Locale.ROOT) : field[1];
                if (v.equals(value)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** A line's key=value fields; a word without key= continues the value before it (a name with spaces). */
    private static List<String[]> fields(String line) {
        List<String[]> fields = new ArrayList<>();
        String[] words = line.split(" ");
        for (int i = 1; i < words.length; i++) {
            String word = words[i];
            int eq = word.indexOf('=');
            if (eq > 0 && word.substring(0, eq).matches("[a-z][a-z-]*")) {
                fields.add(new String[] { word.substring(0, eq), word.substring(eq + 1) });
            } else if (!fields.isEmpty()) {
                String[] last = fields.get(fields.size() - 1);
                last[1] = last[1] + " " + word;
            }
        }
        return fields;
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
import { useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';

// The audit viewer: the sheet's audit lines exactly as the file holds them, newest first — or, with a
// name in the filter, only the lines about that person (name= or person=, compared as names are). It
// reads the file on each show; it is not a second record. A new show clears the old list first. With a name,
// the matching lines of the sheet's descendants follow (each sheet's newest first, sheets by id). For a person
// transferred in, the lines about them from the sheet they came from follow, newest first.
export function AuditViewer() {
  const [sheet] = useSearchParam('sheet', asString);
  const [filter, setFilter] = useState('');
  const show = useMutation({
    mutationFn: (name: string) =>
      getJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/audit?name=${encodeURIComponent(name)}`),
  });
  return (
    <section>
      <form
        data-testid="audit-form"
        onSubmit={(e) => {
          e.preventDefault();
          show.reset();
          show.mutate(filter);
        }}
      >
        <input
          data-testid="audit-filter"
          value={filter}
          placeholder="Person (blank for all)"
          onChange={(e) => {
            setFilter(e.target.value);
            show.reset();
          }}
        />{' '}
        <button type="submit" data-testid="audit-show">Show audit</button>
        {show.isError && <span data-testid="audit-error" role="alert"> Could not read the audit.</span>}
      </form>
      <ul data-testid="audit-list">
        {(show.data ?? []).map((line, i) => (
          <li key={i} data-testid="audit-line">{line}</li>
        ))}
      </ul>
    </section>
  );
}
